const controls=new Set();
function retireRemoved(records){for(const control of controls)if(records.some(record=>[...record.removedNodes].some(node=>node===control.node||node.contains?.(control.node)))){control.retired=true;controls.delete(control)}}
const controlObserver=typeof MutationObserver==='function'?new MutationObserver(retireRemoved):null;
controlObserver?.observe(document.documentElement,{childList:true,subtree:true});
